// Drafts from the hub with the rules tier as fallback (ADR-0006, ADR-0007, ADR-0011, BR-AI-1).
// Photos and ask lines are kept in memory only and never logged.
import {
  DraftResponse,
  type DraftResponseT,
  enforce,
  enforceLadder,
  enforceOsmTags,
  MAX_PHOTO_BYTES,
  TagsDraftResponse,
  type TagsDraftResponseT,
  TEMPLATE_INVITE,
  templateLadder,
} from "@flare/shared";
import { HUB_MODEL } from "@flare/shared/prompts/guard";
import type { Context, Hono } from "hono";
import type { Ctx } from "../core/deps.ts";
import { bumpGlobal } from "../core/gatherings.ts";
import { ApiError } from "../http/errors.ts";
import { body, limitWrite, type RateLimiter } from "../http/middleware.ts";
import { LadderRequest } from "../http/schemas.ts";
import { clientIp } from "../http/write.ts";
import { log } from "../log.ts";
import { aiJob, cloudChat, guardSpan, hubChat } from "../tracing.ts";

/** The photo routes' checks: JPEG only, 1.5 MB at most. The caller zero-fills the buffer. */
async function readJpeg(c: Context): Promise<Buffer> {
  if (c.req.header("content-type") !== "image/jpeg") throw new ApiError(415, "not_jpeg", "Send image/jpeg");
  if (Number(c.req.header("content-length") ?? "0") > MAX_PHOTO_BYTES)
    throw new ApiError(413, "too_large", "1.5 MB at most");
  const buf = Buffer.from(await c.req.arrayBuffer());
  if (buf.length === 0 || buf.length > MAX_PHOTO_BYTES) {
    buf.fill(0);
    throw new ApiError(413, "too_large", "1.5 MB at most");
  }
  if (buf[0] !== 0xff || buf[1] !== 0xd8 || buf[2] !== 0xff) {
    buf.fill(0);
    throw new ApiError(400, "not_jpeg", "Not a JPEG");
  }
  return buf;
}

export function mountAi(app: Hono, ctx: Ctx, rl: RateLimiter): void {
  const count = (name: string, tier: string) => {
    if (ctx.db) bumpGlobal(ctx.db, name, tier).catch(() => log.warn({ event: "counter.failed" }, "counter failed"));
  };

  app.post("/api/v1/drafts", async (c) => {
    limitWrite(rl, { anon: clientIp(c) });
    const optIn = c.req.query("cloud") === "1"; // the host's per-Flare choice (ADR-0022)
    const buf = await readJpeg(c);
    try {
      const out = await aiJob("photo", async (job) => {
        const t = performance.now();
        const present = ctx.relay.status === "connected";
        const r = await hubChat(HUB_MODEL, async (chat) => {
          const res = await ctx.relay.draft(buf);
          chat.set({ "flare.ok": !!res?.ok, ...(res?.model ? { "gen_ai.response.model": res.model } : {}) });
          if (res?.error) chat.set({ "flare.error": res.error });
          return res;
        });
        const guarded =
          r?.ok && r.draft
            ? guardSpan("enforce", (g) => {
                const v = enforce(JSON.stringify(r.draft));
                g.set({ "flare.valid": !!v });
                return v;
              })
            : null;
        const fallback = !present ? "hub_absent" : !r ? "timeout" : !r.ok ? "hub_error" : "invalid";
        // ADR-0022: DigitalOcean only when the hub is absent and the host opted in for this Flare.
        const cloud =
          !guarded && !present && optIn && ctx.cloud
            ? await cloudChat(ctx.cloud.model, () => (ctx.cloud as NonNullable<typeof ctx.cloud>).photo(buf))
            : null;
        const ms = Math.round(performance.now() - t);
        const res: DraftResponseT = guarded
          ? { invite: guarded.invite, alt: guarded.alt, tier: "hub", ms }
          : cloud
            ? { invite: cloud.invite, alt: cloud.alt, tier: "cloud", ms }
            : { invite: TEMPLATE_INVITE, alt: "", tier: "rules", ms };
        job.set({
          "flare.tier": res.tier,
          "flare.ok": res.tier !== "rules",
          ...(res.tier === "hub" ? {} : { "flare.fallback": fallback }),
        });
        return res;
      });
      count("tier_ran.photo", out.tier);
      return c.json(DraftResponse.parse(out));
    } finally {
      buf.fill(0); // drop the photo bytes on every path; nothing is stored (ADR-0011)
    }
  });

  app.post("/api/v1/drafts/ladder", async (c) => {
    limitWrite(rl, { anon: clientIp(c) });
    const b = await body(c, LadderRequest);
    const out = await aiJob("ladder", async (job) => {
      const t = performance.now();
      const present = ctx.relay.status === "connected";
      const r = await hubChat(HUB_MODEL, async (chat) => {
        const res = await ctx.relay.ladder(b, ctx.ladderTimeoutMs);
        chat.set({ "flare.ok": !!res?.ok, ...(res?.model ? { "gen_ai.response.model": res.model } : {}) });
        return res;
      });
      // ML's guard (packages/shared/src/prompts/ladder.ts): one rule set for hub and server.
      const hub =
        r?.ok && r.ladder
          ? guardSpan("enforce_ladder", (g) => {
              const d = enforceLadder(JSON.stringify(r.ladder), { ask: b.ask, total_minutes: b.total_minutes });
              g.set({ "flare.valid": !!d, ...(d ? { "flare.repaired": d.repaired.length } : {}) });
              return d?.ladder ?? null;
            })
          : null;
      // ADR-0022: the ask line is non-personal text; DigitalOcean answers when the hub is absent.
      const cloud =
        !hub && !present && ctx.cloud
          ? await cloudChat(ctx.cloud.model, () =>
              (ctx.cloud as NonNullable<typeof ctx.cloud>).ladder({ ask: b.ask, total_minutes: b.total_minutes }),
            )
          : null;
      const steps = hub ?? cloud ?? templateLadder(b.total_minutes);
      const tier = hub ? "hub" : cloud ? "cloud" : "rules";
      const fallback = !present ? "hub_absent" : !r ? "timeout" : !r.ok ? "hub_error" : "invalid";
      job.set({ "flare.tier": tier, "flare.ok": tier !== "rules", ...(hub ? {} : { "flare.fallback": fallback }) });
      return { steps, tier, ms: Math.round(performance.now() - t) };
    });
    count("tier_ran.ladder", out.tier);
    return c.json(out);
  });

  // ICR-ML5: Fix the map. The hub drafts OSM tags; the guard runs again here; a person reviews
  // every tag on the phone. No cloud tier: the photo is of a street feature, but ADR-0022 sends
  // photos only on a per-Flare opt-in, and there is no Flare here. The photo is never stored.
  app.post("/api/v1/drafts/tags", async (c) => {
    limitWrite(rl, { anon: clientIp(c) });
    const buf = await readJpeg(c);
    try {
      const out = await aiJob("tags", async (job) => {
        const t = performance.now();
        const present = ctx.relay.status === "connected";
        const r = await hubChat(HUB_MODEL, async (chat) => {
          const res = await ctx.relay.tags(buf, ctx.ladderTimeoutMs); // same 8 s budget as the ladder
          chat.set({ "flare.ok": !!res?.ok, ...(res?.model ? { "gen_ai.response.model": res.model } : {}) });
          if (res?.error) chat.set({ "flare.error": res.error });
          return res;
        });
        const tags =
          r?.ok && r.tags
            ? guardSpan("enforce_osm_tags", (g) => {
                const d = enforceOsmTags(JSON.stringify({ tags: r.tags }));
                g.set({ "flare.valid": !!d, ...(d ? { "flare.dropped": d.dropped.length } : {}) });
                return d?.tags ?? null;
              })
            : null;
        const fallback = !present ? "hub_absent" : !r ? "timeout" : !r.ok ? "hub_error" : "invalid";
        const res: TagsDraftResponseT = tags
          ? { tags, tier: "hub", ms: Math.round(performance.now() - t) }
          : { tags: {}, tier: "rules", ms: Math.round(performance.now() - t) };
        job.set({
          "flare.tier": res.tier,
          "flare.ok": res.tier === "hub",
          ...(tags ? {} : { "flare.fallback": fallback }),
        });
        return res;
      });
      count("tier_ran.tags", out.tier);
      return c.json(TagsDraftResponse.parse(out));
    } finally {
      buf.fill(0);
    }
  });
}
// DigitalOcean Serverless Inference as a cloud tier (ADR-0022). Off unless DO_MODEL_ACCESS_KEY
// holds a scoped model access key (an account token is refused, scripts/lib/token-guard.ts).
//   - Plan ladders (non-personal text, at most 80 characters, no place) use it when the hub is
//     absent.
//   - A photo uses it only when the hub is absent AND the host opted in for that Flare
//     (`?cloud=1` on POST /api/v1/drafts). Nothing else ever goes to DigitalOcean.
// Same guards as the hub (enforce(), enforceLadder()). Nothing is stored or logged; the photo
// buffer is zero-filled by the caller. No per-key spend cap exists at DigitalOcean (prepaid
// balance only), so the server caps calls per UTC day and tokens per call.
import { enforce, enforceLadder, type LadderT, SYSTEM_PROMPT, USER_PROMPT } from "@flare/shared";
import { LADDER_PROMPT, ladderUserPrompt } from "@flare/shared/prompts/ladder";
import { accountToken } from "@flare/shared/token-guard";

export const DO_ENDPOINT = "https://inference.do-ai.run/v1/chat/completions";
export const DO_MODEL = "gemma-4-31B-it"; // open Gemma 4, accepts images (probe 2026-10-11: ladder 20.9 s, photo 27.2 s)
export const CLOUD_BUDGET_MS = 35_000;

export type CloudTier = {
  model: string;
  photo(jpeg: Uint8Array): Promise<{ invite: string; alt: string } | null>;
  ladder(input: { ask: string; total_minutes: number }): Promise<LadderT | null>;
  /** Calls left today under the server's cap. */
  left(): number;
};

export function cloudTier(env: NodeJS.ProcessEnv = process.env, fetchImpl: typeof fetch = fetch): CloudTier | null {
  const key = env.DO_MODEL_ACCESS_KEY ?? "";
  if (!key || accountToken(key)) return null;
  const model = env.DO_MODEL ?? DO_MODEL;
  const cap = Number(env.DO_DAILY_MAX_CALLS ?? 60);
  let day = "";
  let used = 0;
  const take = () => {
    const today = new Date().toISOString().slice(0, 10);
    if (today !== day) {
      day = today;
      used = 0;
    }
    if (used >= cap) return false;
    used++;
    return true;
  };

  async function chat(messages: unknown[]): Promise<string | null> {
    if (!take()) return null;
    try {
      const r = await fetchImpl(DO_ENDPOINT, {
        method: "POST",
        headers: { authorization: `Bearer ${key}`, "content-type": "application/json" },
        body: JSON.stringify({ model, messages, temperature: 0, max_tokens: 200 }),
        signal: AbortSignal.timeout(CLOUD_BUDGET_MS),
      });
      if (!r.ok) return null;
      const j = (await r.json()) as { choices?: { message?: { content?: string } }[] };
      return j.choices?.[0]?.message?.content ?? null;
    } catch {
      return null; // timeout, network: the template takes over
    }
  }

  return {
    model,
    left: () => Math.max(0, cap - (day === new Date().toISOString().slice(0, 10) ? used : 0)),
    async photo(jpeg) {
      const b64 = Buffer.from(jpeg).toString("base64");
      const text = await chat([
        { role: "system", content: SYSTEM_PROMPT },
        {
          role: "user",
          content: [
            { type: "text", text: USER_PROMPT },
            { type: "image_url", image_url: { url: `data:image/jpeg;base64,${b64}` } },
          ],
        },
      ]);
      const d = text ? enforce(text) : null;
      return d ? { invite: d.invite, alt: d.alt } : null;
    },
    async ladder(input) {
      const text = await chat([
        { role: "system", content: LADDER_PROMPT.system },
        { role: "user", content: ladderUserPrompt(input) },
      ]);
      return text ? (enforceLadder(text, input)?.ladder ?? null) : null;
    },
  };
}
// Plan ladder draft (FR-AI-9, SRS-PLAN-2, BR-P-4). Text in, 4 steps out, on the hub tier.
// The job carries only the ask, the total minutes and coarse weather (asyncapi ladderJob);
// places come from the phone's map pack, so the model writes labels and minutes only.
import { z } from "zod";
import { clipWords, countWords, extractJson, hasPersonWords, type PromptSpec } from "./guard.ts";

/** v1 used {"steps":[{step,label,minutes}...]} and took 6.4 to 8.8 s; v2 asks for two short arrays (docs/ml/model-cards.md). */
export const LADDER_PROMPT_VERSION = 2;

/** Fixed labels for the template tier. Same text as copy keys ladder.template.step1 to step4. */
export const TEMPLATE_LABELS = ["The full plan", "A shorter loop", "A quick lap", "A quick hello"] as const;

export const LADDER_SYSTEM = [
  "You plan short outings for Flare, an app that gets close friends outside.",
  "A Plan has 4 steps. Step 1 is the biggest version, step 4 the smallest. Friends pick the biggest step everyone can do.",
  "Reply with one JSON object only. No code fences, no other text.",
  '{"labels": ["...", "...", "...", "..."], "minutes": [60, 30, 15, 10]}',
  "labels: 4 labels, biggest first. Each is 2 to 4 plain words, lower case except the first letter. Say what the group does, like a walk, a loop or a sit.",
  "minutes: 4 whole numbers in the same order. Step 1 uses the total minutes given. Each step is shorter than the one before. Step 4 is at least 5.",
  "Use only places named in the ask. Never invent place names, shops, food or events.",
  "If rain is likely, prefer covered or short steps. Never mention people, names, faces, age or gender.",
].join("\n");

export const LadderInput = z.object({
  ask: z.string().max(80),
  total_minutes: z.number().int().min(40).max(600),
  weather: z.object({ rain_likely: z.boolean().optional(), temp_f: z.number().int().optional() }).optional(),
});
export type LadderInputT = z.infer<typeof LadderInput>;

export const LadderStep = z.object({
  step: z.number().int().min(1).max(4),
  label: z.string().min(1),
  minutes: z.number().int().min(5),
});
/** The guarded ladder (asyncapi result.ladder): 4 steps, 1..4 in order, strictly decreasing, labels ≤ 4 words. */
export const Ladder = z
  .array(LadderStep)
  .length(4)
  .refine((l) => l.every((s, i) => s.step === i + 1), "steps must be 1 to 4 in order")
  .refine((l) => l.every((s, i) => i === 0 || s.minutes < (l[i - 1]?.minutes ?? 0)), "minutes must decrease")
  .refine((l) => l.every((s) => countWords(s.label) <= 4), "labels ≤ 4 words");
export type LadderT = z.infer<typeof Ladder>;

/** Remove quotes and line breaks from the ask so it reads as data inside the prompt. */
export const cleanAsk = (ask: string): string =>
  ask
    .replace(/[\r\n\t"`{}<>]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 80);

export function ladderUserPrompt(input: LadderInputT): string {
  const lines = [`Ask: "${cleanAsk(input.ask)}"`, `Total minutes for step 1: ${input.total_minutes}`];
  const w = input.weather;
  if (w && (w.rain_likely !== undefined || w.temp_f !== undefined)) {
    const parts = [w.rain_likely ? "rain likely" : w.rain_likely === false ? "no rain expected" : null];
    if (w.temp_f !== undefined) parts.push(`${w.temp_f} F`);
    lines.push(`Weather: ${parts.filter(Boolean).join(", ")}`);
  }
  lines.push("Reply with the JSON.");
  return lines.join("\n");
}

export const LADDER_PROMPT: PromptSpec = {
  id: "ladder-draft",
  version: LADDER_PROMPT_VERSION,
  system: LADDER_SYSTEM,
  budgetMs: 8000,
  numPredict: 80,
};

const round5 = (n: number) => Math.max(5, Math.round(n / 5) * 5);

/** Template minutes: total × 1, 0.5, 0.25, 0.125, rounded to 5, kept strictly decreasing (60 → 60, 30, 15, 10). */
export function templateMinutes(total: number): number[] {
  const m = [1, 0.5, 0.25, 0.125].map((f) => round5(total * f));
  m[0] = total;
  for (let i = 1; i < 4; i++) {
    const prev = m[i - 1] ?? 5;
    if ((m[i] ?? 0) >= prev) m[i] = prev - 5;
  }
  return m;
}

/** The template tier ladder (BR-AI-1 floor). Always valid for total_minutes 40 to 600. */
export function templateLadder(total: number): LadderT {
  const mins = templateMinutes(total);
  return TEMPLATE_LABELS.map((label, i) => ({ step: (i + 1) as 1 | 2 | 3 | 4, label, minutes: mins[i] ?? 5 }));
}

const STOP = new Set(["A", "An", "The", "I", "OK"]);

/**
 * Capitalised words not at the start of the label and not in the ask look like invented
 * place names (guardrail: never invent places). "Walk to Fairlane" passes when the ask says Fairlane.
 */
export function inventsNames(label: string, ask: string): boolean {
  const askWords = new Set((ask.match(/[\p{L}']+/gu) ?? []).map((w) => w.toLowerCase()));
  const words = label.match(/[\p{L}']+/gu) ?? [];
  return words.some((w, i) => i > 0 && /^\p{Lu}/u.test(w) && !STOP.has(w) && !askWords.has(w.toLowerCase()));
}

/** Accept v2 {labels, minutes}, v1 {steps: [...]}, or a bare array of steps. */
function toSteps(raw: unknown): unknown[] | null {
  if (Array.isArray(raw)) return raw;
  if (!raw || typeof raw !== "object") return null;
  const o = raw as { steps?: unknown; labels?: unknown; minutes?: unknown };
  if (Array.isArray(o.steps)) return o.steps;
  if (Array.isArray(o.labels)) {
    const mins = Array.isArray(o.minutes) ? o.minutes : [];
    return o.labels.map((label, i) => ({ label, minutes: mins[i] }));
  }
  return null;
}

export type LadderDraft = { ladder: LadderT; repaired: string[]; templateSteps: number };

/**
 * Guard a ladder answer (SRS-AI-2). Per step: a label that is empty, too long after clipping,
 * names a person or invents a place is replaced by the template label (FR-PLAN-4). Minutes
 * that break BR-P-4 are replaced as a set by the template minutes. Returns null when the
 * answer is not usable JSON or no model label survives, so the caller uses templateLadder().
 */
export function enforceLadder(text: string, input: LadderInputT): LadderDraft | null {
  const raw = extractJson(text);
  const list = toSteps(raw);
  if (!Array.isArray(list) || list.length < 4) return null;
  const repaired: string[] = [];
  if (list.length > 4) repaired.push(`steps:clipped ${list.length}->4`);
  const items = list.slice(0, 4) as { label?: unknown; minutes?: unknown }[];
  let templateSteps = 0;
  const seen = new Set<string>();
  const labels = items.map((it, i) => {
    const fallback = TEMPLATE_LABELS[i] ?? "A quick hello";
    if (typeof it?.label !== "string") {
      templateSteps++;
      repaired.push(`step${i + 1}:label template`);
      return fallback;
    }
    const l = clipWords(it.label, 4, `step${i + 1}`, repaired).replace(/[.!]+$/, "");
    const key = l.toLowerCase();
    const dup = seen.has(key);
    seen.add(key);
    // A repeated label would make two steps look the same on the ladder.
    if (!l || dup || hasPersonWords(l) || inventsNames(l, input.ask)) {
      templateSteps++;
      repaired.push(`step${i + 1}:label template`);
      return fallback;
    }
    return l;
  });
  if (templateSteps === 4) return null;
  let minutes = items.map((it) => (typeof it?.minutes === "number" ? Math.round(it.minutes) : Number.NaN));
  if (minutes[0] !== input.total_minutes && Number.isFinite(minutes[0])) {
    repaired.push(`step1:minutes ${minutes[0]}->${input.total_minutes}`);
    minutes[0] = input.total_minutes;
  }
  const ok = minutes.every((m, i) => Number.isFinite(m) && m >= 5 && (i === 0 || m < (minutes[i - 1] ?? 0)));
  if (!ok) {
    repaired.push("minutes:template");
    minutes = templateMinutes(input.total_minutes);
  }
  const ladder = labels.map((label, i) => ({ step: (i + 1) as 1 | 2 | 3 | 4, label, minutes: minutes[i] ?? 5 }));
  const checked = Ladder.safeParse(ladder);
  if (!checked.success) return null;
  return { ladder: checked.data, repaired, templateSteps };
}

