import { runOsmTags } from "./tasks/osm-tags.ts";
import { runPhoto } from "./tasks/photo.ts";
import { runRestLoop } from "./tasks/rest-loop.ts";

const { values, positionals } = parseArgs({
  allowPositionals: true,
  options: {
    tier: { type: "string" },
    limit: { type: "string" },
    parser: { type: "string" },
    strict: { type: "boolean", default: false },
  },
});

const TASKS = ["photo", "ladder", "conditions", "rest-loop", "osm-tags"] as const;
type Task = (typeof TASKS)[number];
const DEFAULT_TIER: Record<Task, string> = {
  photo: "hub",
  ladder: "hub",
  conditions: "rules",
  "rest-loop": "rules",
  "osm-tags": "hub",
};
const MODEL_TIERS = new Set(["hub", "model"]);

const task = positionals[0] ?? "";
const list: Task[] = task === "all" ? [...TASKS] : TASKS.includes(task as Task) ? [task as Task] : [];
if (!list.length) {
  console.error(`usage: npm run eval -- <${TASKS.join("|")}|all> [--tier hub|rules] [--limit n] [--strict]`);
  process.exit(2);
}
const limit = values.limit ? Number(values.limit) : undefined;

let warmed = false;
let failed = false;
for (const t of list) {
  const tier = values.tier ?? DEFAULT_TIER[t];
  if (MODEL_TIERS.has(tier) && !warmed) {
    if (!(await modelReady())) {
      console.error(`Ollama model ${MODEL} not available; start Ollama or pass --tier rules`);
      process.exit(3);
    }
    const ms = await warm();
    console.info(`warm-up ${ms} ms (not counted)`);
    warmed = true;
  }
  const load0 = loadavg()[0] ?? 0;
  let r: Report;
  if (t === "photo") r = await runPhoto(tier, limit);
  else if (t === "ladder") r = await runLadder(tier, limit);
  else if (t === "conditions") r = await runConditions(tier, values.parser);
  else if (t === "rest-loop") r = await runRestLoop(tier, values.parser, limit);
  else r = await runOsmTags(tier, limit);
  if (MODEL_TIERS.has(tier))
    r.notes.push(
      `Mac 1-min load average: ${load0.toFixed(1)} at start, ${(loadavg()[0] ?? 0).toFixed(1)} at end (10 cores; other agents share this Mac and its Ollama).`,
    );
  const out = writeReport(r);
  console.info(`\n${r.task} (${r.tier}) n=${r.n}${r.latency ? ` median ${r.latency.median_ms} ms` : ""}`);
  for (const b of r.bars) console.info(`  ${b.pass ? "pass" : "FAIL"}  ${b.name}: ${b.value} (target ${b.target})`);
  console.info(`  report: ${out}`);
  if (!allPass(r)) failed = true;
}
if (values.strict && failed) process.exit(1);
// Minimal Ollama client for evals, with the hub's settings (lab 02, architecture 07 B3).
// Calls are sequential by design: the Ollama on this Mac is shared by several agents.
import { HUB_MODEL, OLLAMA_OPTIONS } from "../../packages/shared/src/prompts/guard.ts";

export const OLLAMA_URL = process.env.OLLAMA_URL ?? "http://127.0.0.1:11434";
export const MODEL = process.env.EVAL_MODEL ?? HUB_MODEL;

export type ChatIn = { system: string; user: string; imageBase64?: string; numPredict?: number; timeoutMs?: number };
export type ChatOut = { text: string; ms: number; error?: string };

export async function chat(input: ChatIn): Promise<ChatOut> {
  const body = {
    model: MODEL,
    stream: false,
    think: false,
    keep_alive: "10m",
    messages: [
      { role: "system", content: input.system },
      input.imageBase64
        ? { role: "user", content: input.user, images: [input.imageBase64] }
        : { role: "user", content: input.user },
    ],
    options: { ...OLLAMA_OPTIONS, num_predict: input.numPredict ?? OLLAMA_OPTIONS.num_predict },
  };
  const t0 = performance.now();
  try {
    const res = await fetch(`${OLLAMA_URL}/api/chat`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(input.timeoutMs ?? 60_000),
    });
    const ms = Math.round(performance.now() - t0);
    if (!res.ok) return { text: "", ms, error: `http ${res.status}` };
    const json = (await res.json()) as { message?: { content?: string } };
    return { text: json.message?.content ?? "", ms };
  } catch (e) {
    return { text: "", ms: Math.round(performance.now() - t0), error: (e as Error).name };
  }
}

export async function modelReady(): Promise<boolean> {
  try {
    const res = await fetch(`${OLLAMA_URL}/api/tags`, { signal: AbortSignal.timeout(3000) });
    const tags = (await res.json()) as { models?: { name: string }[] };
    return !!tags.models?.some((m) => m.name === MODEL);
  } catch {
    return false;
  }
}

/** One untimed request so the cold load (7 to 14 s, lab 02) is not counted in latency. */
export async function warm(): Promise<number> {
  const r = await chat({ system: "Reply with {}", user: "{}", numPredict: 4, timeoutMs: 120_000 });
  return r.ms;
}

/**
